-- Generated from constructor signatures. Do not edit; see source_imports.contracts.
CREATE FUNCTION atlas.nonblank(value text) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $nonblank$
 SELECT value COLLATE "C" ~  E'[^\\u0009-\\u000d\\u0020\\u0085\\u00a0\\u1680\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]';
$nonblank$;

CREATE FUNCTION atlas.valid_construction_record(method text, arguments jsonb)
RETURNS boolean LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $contract$
SELECT CASE method
WHEN 'geodesic_trace' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Source Ids","type":"array"},"source_feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Feature Id","type":"string"},"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"basis":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basis","type":"string"},"points":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"type":"array"},"title":"Points","type":"array"},"max_step_metres":{"title":"Max Step Metres","type":"number"},"source_location":{"anyOf":[{"additionalProperties":true,"type":"object"},{"type":"string"},{"type":"null"}],"title":"Source Location"}},"required":["source_ids","source_feature_id","feature_id","basis","points","max_step_metres"],"title":"geodesic_trace","type":"object"}'::json, arguments)
WHEN 'interpreted_geometry' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"Point":{"additionalProperties":false,"properties":{"type":{"const":"Point","title":"Type","type":"string"},"coordinates":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"title":"Coordinates","type":"array"}},"required":["type","coordinates"],"title":"Point","type":"object"},"Polygon":{"additionalProperties":false,"properties":{"type":{"const":"Polygon","title":"Type","type":"string"},"coordinates":{"items":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"type":"array"},"type":"array"},"title":"Coordinates","type":"array"}},"required":["type","coordinates"],"title":"Polygon","type":"object"},"Selection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"geometry":{"anyOf":[{"$ref":"#/$defs/Point"},{"$ref":"#/$defs/Polygon"}],"title":"Geometry"}},"required":["feature_id","geometry"],"title":"Selection","type":"object"}},"additionalProperties":false,"properties":{"source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Source Ids","type":"array"},"basis":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basis","type":"string"},"selections":{"items":{"$ref":"#/$defs/Selection"},"title":"Selections","type":"array"}},"required":["source_ids","basis","selections"],"title":"interpreted_geometry","type":"object"}'::json, arguments)
WHEN 'osm_way_chain' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","additionalProperties":false,"properties":{"way_source_ids":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Way Source Ids","type":"array"},"start_node_id":{"title":"Start Node Id","type":"integer"},"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"basis":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basis","type":"string"},"evidence_source_ids":{"anyOf":[{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"type":"array"},{"type":"null"}],"title":"Evidence Source Ids"}},"required":["way_source_ids","start_node_id","feature_id","basis"],"title":"osm_way_chain","type":"object"}'::json, arguments)
WHEN 's130_areas' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"FeatureIdentity":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"}},"required":["feature_id","source_feature_id"],"title":"FeatureIdentity","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"basis":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basis","type":"string"},"gml_member":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Gml Member","type":"string"},"gml_sha256":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Gml Sha256","type":"string"},"selections":{"items":{"$ref":"#/$defs/FeatureIdentity"},"title":"Selections","type":"array"}},"required":["source_id","basis","gml_member","gml_sha256","selections"],"title":"s130_areas","type":"object"}'::json, arguments)
WHEN 'selected_osm_features' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"OsmSelection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"},"object_type":{"enum":["node","way","relation"],"title":"Object Type","type":"string"},"object_version":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Object Version"},"expected_tags":{"additionalProperties":{"type":"string"},"title":"Expected Tags","type":"object"},"parent_relation":{"$ref":"#/$defs/ParentRelation"},"ignored_member_roles":{"items":{"maxItems":2,"minItems":2,"prefixItems":[{"enum":["n","w","r"],"type":"string"},{"type":"string"}],"type":"array"},"title":"Ignored Member Roles","type":"array"},"ring_anchors":{"items":{"$ref":"#/$defs/RingAnchor"},"title":"Ring Anchors","type":"array"},"holes":{"enum":["preserve","outer_envelope"],"title":"Holes","type":"string"},"geometry_type":{"enum":["Polygon","MultiPolygon"],"title":"Geometry Type","type":"string"}},"required":["feature_id","source_feature_id","object_type","object_version"],"title":"OsmSelection","type":"object"},"ParentRelation":{"additionalProperties":false,"properties":{"id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Id"},"version":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Version"},"role":{"title":"Role","type":"string"},"expected_tags":{"additionalProperties":{"type":"string"},"title":"Expected Tags","type":"object"}},"required":["id","version","role"],"title":"ParentRelation","type":"object"},"RingAnchor":{"additionalProperties":false,"properties":{"node_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Node Id"},"way_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Way Id"},"node_version":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Node Version"},"expected_tags":{"additionalProperties":{"type":"string"},"title":"Expected Tags","type":"object"}},"required":["node_id","way_id","node_version","expected_tags"],"title":"RingAnchor","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"basis":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basis","type":"string"},"selections":{"items":{"$ref":"#/$defs/OsmSelection"},"title":"Selections","type":"array"}},"required":["source_id","basis","selections"],"title":"selected_osm_features","type":"object"}'::json, arguments)
WHEN 'selected_vector_features' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"VectorSelection":{"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"source_feature_id":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"integer"}],"title":"Source Feature Id"},"collection":{"title":"Collection","type":"boolean"},"expected_feature_count":{"title":"Expected Feature Count","type":"integer"},"polygon_containing":{"maxItems":2,"minItems":2,"prefixItems":[{"type":"number"},{"type":"number"}],"title":"Polygon Containing","type":"array"},"holes":{"enum":["preserve","outer_envelope"],"title":"Holes","type":"string"}},"required":["feature_id","source_feature_id"],"title":"VectorSelection","type":"object"}},"additionalProperties":false,"properties":{"source_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Source Id","type":"string"},"basis":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basis","type":"string"},"id_field":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Id Field","type":"string"},"selections":{"items":{"$ref":"#/$defs/VectorSelection"},"title":"Selections","type":"array"},"member":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"null"}],"title":"Member"},"layer":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"null"}],"title":"Layer"},"coordinate_operation":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"type":"null"}],"title":"Coordinate Operation"}},"required":["source_id","basis","id_field","selections"],"title":"selected_vector_features","type":"object"}'::json, arguments)
WHEN 'watershed_boundary' THEN public.jsonb_matches_schema( E'{"$schema":"https://json-schema.org/draft/2020-12/schema","$defs":{"MultipartSource":{"additionalProperties":false,"properties":{"parts":{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"title":"Parts","type":"array"},"sha256":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Sha256","type":"string"},"size_bytes":{"title":"Size Bytes","type":"integer"},"filename":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Filename","type":"string"}},"required":["parts","sha256","size_bytes","filename"],"title":"MultipartSource","type":"object"}},"additionalProperties":false,"properties":{"feature_id":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Feature Id","type":"string"},"basis":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","title":"Basis","type":"string"},"sources":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"anyOf":[{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},{"$ref":"#/$defs/MultipartSource"}]}},"title":"Sources","type":"object"},"lines":{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"items":{"additionalProperties":true,"type":"object"},"type":"array"}},"title":"Lines","type":"object"},"sections":{"items":{"additionalProperties":true,"type":"object"},"title":"Sections","type":"array"},"joins":{"items":{"additionalProperties":true,"type":"object"},"title":"Joins","type":"array"},"start":{"additionalProperties":true,"title":"Start","type":"object"},"end":{"additionalProperties":true,"title":"End","type":"object"},"terrains":{"anyOf":[{"additionalProperties":false,"patternProperties":{"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]":{"additionalProperties":true,"type":"object"}},"type":"object"},{"type":"null"}],"title":"Terrains"},"evidence_sources":{"anyOf":[{"items":{"pattern":"[^\\\\u0009-\\\\u000d\\\\u0020\\\\u0085\\\\u00a0\\\\u1680\\\\u2000-\\\\u200a\\\\u2028\\\\u2029\\\\u202f\\\\u205f\\\\u3000]","type":"string"},"type":"array"},{"type":"null"}],"title":"Evidence Sources"},"geographic_choices":{"anyOf":[{"additionalProperties":true,"type":"object"},{"type":"null"}],"title":"Geographic Choices"}},"required":["feature_id","basis","sources","lines","sections","joins","start","end"],"title":"watershed_boundary","type":"object"}'::json, arguments)
ELSE FALSE END;
$contract$;

CREATE FUNCTION atlas.construction_source_ids(method text, arguments jsonb)
RETURNS SETOF text LANGUAGE sql IMMUTABLE PARALLEL SAFE AS $sources$
SELECT DISTINCT value #>> '{}' FROM unnest(CASE method
WHEN 'geodesic_trace' THEN ARRAY['lax $."source_ids"[*]']::jsonpath[]
WHEN 'interpreted_geometry' THEN ARRAY['lax $."source_ids"[*]']::jsonpath[]
WHEN 'osm_way_chain' THEN ARRAY['lax $."evidence_source_ids"[*]','lax $."way_source_ids"[*]']::jsonpath[]
WHEN 's130_areas' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'selected_osm_features' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'selected_vector_features' THEN ARRAY['lax $."source_id"']::jsonpath[]
WHEN 'watershed_boundary' THEN ARRAY['lax $."evidence_sources"[*]','lax $."sources".*','lax $."sources".*."parts"[*]']::jsonpath[]
ELSE ARRAY[]::jsonpath[] END) AS paths(path)
CROSS JOIN LATERAL jsonb_path_query(arguments,path,'{}'::jsonb,true) AS refs(value)
WHERE jsonb_typeof(value)='string';
$sources$;
